      const landedFloorGraceSec = existing?.landed === true && Number.isSafeInteger(existing?.targetGraceSec) ? existing.targetGraceSec : 0;
      const targetGraceSec = pendingTargetGraceSec ?? Math.min(maxGraceSec, Math.max(landedFloorGraceSec, neededGraceSec));
