        lastSeenAt: now,
        attempts: (origin === "roster_gate" ? prev.origin === "roster_gate" && ["chain_unreadable", "env_chain_mismatch", "roster_gate_unreadable"].includes(prev.cause) ? prev.attempts || 0 : 0 : prev.attempts || 0) + 1,
        deadlineMs,
        deadlineSource: source,
        snapshotReadAt: readAt,
        rpcConfig: rpcConfig || describeRpcConfig(this.env),
        // S3-008（ユーザー要望・2026-07-29）: 通知は**トラブル1件につき1回**。
        // 30分ごとの再試行のたびに送るとメールが埋まるため、
        //   ・初回検出
