      evidenceSegmentPrice(version4);
      if (progress?.evidenceSegmentPinVersion && progress.evidenceSegmentPinVersion !== version4 || earlyPin && earlyPin !== version4) {
        throw new Error(`[evidence-segments] pinned version changed for ${key}`);
      }
      if (progress && !progress.evidenceSegmentPinVersion) {
        progress.evidenceSegmentPinVersion = version4;
      } else if (!progress && !earlyPin) {
        await this.storage.put(pinKey, version4);
      }
