      const tag = tags[0];
      const isSpectator = tag?.startsWith("spectator:");
      const uid2 = isSpectator ? tag.replace("spectator:", "") : tag;
      console.log(`WebSocket closed: uid=${uid2}${isSpectator ? " (spectator)" : ""}, code=${code}`);
      if (uid2 && !isSpectator && !this.hasOtherOpenSocketOfUid(uid2, ws)) {
        this.broadcast({
          type: "member_disconnected",
          uid: uid2
        }, uid2);
      }
